function nextPage(rows, cursor, size) {
  // rows: ascending array of day numbers; cursor: last day already shown (or null)
  let start = 0;
  if (cursor !== null) {
    while (start < rows.length && rows[start] < cursor) start++;
  }
  return rows.slice(start, start + size);
}

